import {SECTORS,STATES,money,round,today,uid,esc,empty,calculate,clients,totals,normalize,recommendations} from './core.mjs';
const KEY='emprendecopilot-platform-v3';const $=id=>document.getElementById(id);let data=empty(),page='home',orderTab='orders',orderFilter='all',orderSearch='',financeMonth='all',reminderFilter='pending',undo=null,toastTimer,importData;
try{const saved=localStorage.getItem(KEY);if(saved)data=normalize(JSON.parse(saved));else{const old=localStorage.getItem('ec2');if(old){data=normalize(JSON.parse(old));localStorage.setItem(KEY,JSON.stringify(data));}else{const welcome=JSON.parse(localStorage.getItem('emprendecopilot-demo')||'null');if(welcome){data.business=String(welcome.business||'').slice(0,120);data.owner=String(welcome.name||'').slice(0,80);data.sector=SECTORS[welcome.sector]?welcome.sector:'Otro';}}}}catch(e){$('storage-warning').hidden=false;$('storage-warning').textContent='No se pudo leer el guardado local. Los registros existentes no se sobrescribirán hasta que guardes un cambio; puedes importarlos desde un respaldo.';}
const iconPaths={home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',orders:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M9 3h6v4H9zM8 12h8M8 16h6"/>',costs:'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="M8 6h8M8 11h1M15 11h1M8 15h1M15 15h1M8 19h1M15 19h1"/>',finances:'<path d="M3 20h18M5 15l5-6 4 3 6-8M15 4h5v5"/>',reminders:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 11h18M8 15h2M14 15h2"/>',settings:'<path d="M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z"/><circle cx="12" cy="12" r="3"/>',edit:'<path d="M14 4l6 6M3 21l5-1L21 7l-5-5L3 15z"/>',delete:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="M15 15l6 6"/>',client:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',spark:'<path d="M12 3l3 6 6 3-6 3-3 6-3-6-6-3 6-3z"/>'};
const svg=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[k]||iconPaths.spark}</svg>`;
const initials=s=>s.trim().split(/\s+/).slice(0,2).map(w=>w[0]||'').join('').toUpperCase()||'EC';
const cfg=()=>SECTORS[data.sector]||SECTORS.Otro;
const dateLabel=d=>d?new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'short'}).format(new Date(d+'T12:00:00Z')):'Sin fecha';
const fullDate=d=>d?new Intl.DateTimeFormat('es-PE',{day:'numeric',month:'long',year:'numeric',timeZone:'America/Lima'}).format(new Date(d+'T12:00:00Z')):'Sin fecha';
const btn=(text,action,cls='btn')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const heading=(title,subtitle,actions='',eyebrow='TU NEGOCIO, BAJO CONTROL')=>`<div class="page-heading"><div><small>${eyebrow}</small><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;
const emptyBox=(title,body,key='orders',action='')=>`<div class="empty-state"><span class="empty-icon">${svg(key)}</span><strong>${title}</strong><p>${body}</p>${action?btn('Dar el primer paso →',action,'btn secondary small'):''}</div>`;
const actions=(type,id)=>`<div class="row-actions"><button class="row-action" data-action="edit-${type}" data-id="${esc(id)}" aria-label="Editar ${type==='order'?'pedido':type==='movement'?'movimiento':type==='product'?'producto':'recordatorio'}">${svg('edit')}</button><button class="row-action" data-action="delete-${type}" data-id="${esc(id)}" aria-label="Eliminar ${type==='order'?'pedido':type==='movement'?'movimiento':type==='product'?'producto':'recordatorio'}">${svg('delete')}</button></div>`;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(data));$('storage-warning').hidden=true;return true}catch{$('storage-warning').hidden=false;$('storage-warning').textContent='No se pudo guardar en este navegador. Exporta un respaldo para conservar los cambios.';return false}}
function notice(message,undoCallback){clearTimeout(toastTimer);undo=undoCallback||null;$('toast').querySelector('span').textContent=message;$('toast').querySelector('button').hidden=!undo;$('toast').hidden=false;toastTimer=setTimeout(()=>{$('toast').hidden=true;undo=null},8000)}
function changed(message){const saved=persist();render();notice(saved?message:message+' · Exporta un respaldo; no se pudo guardar.');}
const labels={home:'Inicio',orders:'Pedidos',costs:'Costos',finances:'Finanzas',reminders:'Recordatorios',settings:'Mi negocio y respaldo'};
function nav(){const t=totals(data);$('main-nav').innerHTML=Object.entries(labels).filter(([k])=>k!=='settings').map(([k,v])=>`<button class="nav-btn ${page===k?'active':''}" data-page="${k}" ${page===k?'aria-current="page"':''}><span class="nav-icon">${svg(k)}</span>${v}${k==='orders'&&t.pending?`<span class="nav-count">${t.pending}</span>`:''}${k==='reminders'&&data.reminders.some(r=>!r.done)?`<span class="nav-count">${data.reminders.filter(r=>!r.done).length}</span>`:''}</button>`).join('');$('settings-nav').classList.toggle('active',page==='settings');$('settings-nav').querySelector('.nav-icon').innerHTML=svg('settings');$('business-name').textContent=data.business||'Mi emprendimiento';$('business-sector').textContent=data.sector||'Configura tu negocio';document.querySelector('.business-avatar').textContent=initials(data.business);document.querySelector('.owner-avatar').textContent=initials(data.owner||data.business);$('crumb').textContent=labels[page];}
function go(p){page=labels[p]?p:'home';location.hash=page;render();closeMenu();$('content').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function stat(label,value,note,key,cls=''){return `<article class="stat"><span>${label}</span><strong class="${cls}">${value}</strong><small>${note}</small><i class="stat-glyph">${svg(key)}</i></article>`}
function chart(){const days=Array.from({length:7},(_,i)=>{const d=new Date(today()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-6+i);return d.toISOString().slice(0,10)});const series=days.map(d=>{const sales=data.orders.filter(o=>o.state===2&&(o.deliveredAt||o.created)===d).reduce((s,o)=>s+o.amount,0);const m=data.movements.filter(m=>m.date===d);return {date:d,income:round(sales+m.filter(x=>x.type==='Ingreso').reduce((s,x)=>s+x.amount,0)),expense:round(m.filter(x=>x.type==='Gasto').reduce((s,x)=>s+x.amount,0))}});const max=Math.max(10,...series.flatMap(v=>[v.income,v.expense]));const path=k=>series.map((v,i)=>`${i?'L':'M'} ${i*100} ${135-v[k]/max*115}`).join(' ');return `<div class="chart-legend"><span><i></i> Ingresos</span><span><i class="expense"></i> Gastos</span></div><div class="chart-wrap"><svg viewBox="-5 0 610 150" preserveAspectRatio="none" role="img" aria-label="Ingresos y gastos de los últimos siete días"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b999ed" stop-opacity=".2"/><stop offset="1" stop-color="#b999ed" stop-opacity="0"/></linearGradient></defs><path d="M0 20H600M0 58H600M0 96H600M0 135H600" stroke="#eef0f6" stroke-dasharray="3 4"/><path d="${path('income')} L600 145L0 145Z" fill="url(#area)"/><path d="${path('income')}" fill="none" stroke="#a17be1" stroke-width="2.5" vector-effect="non-scaling-stroke"/><path d="${path('expense')}" fill="none" stroke="#82bda8" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>${series.every(d=>!d.income&&!d.expense)?'<div class="chart-zero">Cada movimiento cuenta.<br>Registra ingresos o gastos para ver tu progreso.</div>':''}</div><div class="chart-labels">${series.map(d=>`<span>${dateLabel(d.date)}</span>`).join('')}</div><details class="chart-desc"><summary>Ver cifras del gráfico</summary>${series.map(d=>`${fullDate(d.date)}: ingresos ${money(d.income)}, gastos ${money(d.expense)}`).join('<br>')}</details><div class="chart-desc">Los registros antiguos sin fecha se incluyen en el balance total, pero no en el gráfico.</div>`}
function orderTable(list,compact=false){if(!list.length)return emptyBox('Todo empieza con tu primer pedido','Registra un cliente, un producto o servicio y su importe.','orders','new-order');return `<div class="table-scroll"><table><thead><tr><th>CLIENTE</th><th>DETALLE</th>${compact?'':'<th>ENTREGA</th>'}<th>ESTADO</th><th style="text-align:right">IMPORTE</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody>${list.map(o=>`<tr><td><div class="client-cell"><span class="avatar">${esc(initials(o.client))}</span><div><strong>${esc(o.client)}</strong><small>${esc(o.phone||'Sin celular')}</small></div></div></td><td class="detail-cell">${esc(o.detail)}</td>${compact?'':`<td>${dateLabel(o.delivery)}</td>`}<td><button class="badge state-${o.state}" data-action="cycle-order" data-id="${esc(o.id)}" aria-label="Cambiar estado del pedido de ${esc(o.client)}, actualmente ${STATES[o.state]}">${STATES[o.state]}</button></td><td class="money-cell">${money(o.amount)}</td><td>${actions('order',o.id)}</td></tr>`).join('')}</tbody></table></div>`}
function home(){const t=totals(data),due=data.reminders.filter(r=>!r.done).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')).slice(0,3);const name=data.owner?`, ${esc(data.owner.split(' ')[0])}`:'';return heading(`Tu negocio tiene rumbo${name}.`,'Una vista clara de lo que vendes, lo que gastas y lo que viene.',btn('✦ Preguntarle a Copilot','copilot','btn secondary')+btn('+ Nuevo pedido','new-order'),new Intl.DateTimeFormat('es-PE',{weekday:'long',day:'numeric',month:'long',timeZone:'America/Lima'}).format(new Date()).toUpperCase())+(!data.business||!data.sector?`<div class="onboarding"><img src="logo-icon.svg" alt=""><div><strong>Hagamos que este espacio sea tuyo.</strong><p>Cuéntanos el nombre y rubro de tu negocio para adaptar las recomendaciones.</p></div>${btn('Configurar mi negocio →','business','btn ghost small')}</div>`:'')+`<div class="stats">${stat('Pedidos por entregar',t.pending,'Pendientes y en proceso','orders')}${stat('Ingresos registrados',money(t.income),'Entregados + ingresos manuales','finances')}${stat('Gastos registrados',money(t.expenses),'Movimientos de gastos','costs')}${stat('Balance del negocio',money(t.net),'Ingresos menos gastos registrados','finances',t.net<0?'negative':'positive')}</div><div class="grid-two"><section class="panel"><div class="panel-header"><div><h2>Tu negocio en movimiento</h2><p>Lo que entra y lo que sale. Sin complicaciones.</p></div><span>Últimos 7 días</span></div>${chart()}</section><section class="panel"><div class="panel-header"><h2>Tu agenda</h2><button class="panel-link" data-page="reminders">Ver todo →</button></div>${due.length?due.map(r=>`<div class="agenda-row ${r.date&&r.date<today()?'warning':''}"><span class="agenda-date">${dateLabel(r.date)}<br>${esc(r.time)}</span><div class="agenda-text"><strong>${esc(r.title)}</strong><small>${r.kind}${r.date&&r.date<today()?' · Vencido':''}</small></div><input type="checkbox" aria-label="Completar ${esc(r.title)}" data-action="toggle-reminder" data-id="${esc(r.id)}"></div>`).join(''):emptyBox('Un día organizado empieza aquí','Agrega pagos, entregas o citas a tu agenda.','reminders','new-reminder')}</section></div><div class="panel-header"><h2>Una mirada de tu Copilot</h2><span>Recomendaciones locales de prueba</span></div><div class="recommendations">${recommendations(data).map(r=>`<button class="insight ${r.tone}" data-page="${r.page}"><span>✦</span><div><strong>${esc(r.title)}</strong><p>${esc(r.body)}</p></div></button>`).join('')}</div><section class="panel"><div class="panel-header"><h2>Pedidos recientes</h2><button class="panel-link" data-page="orders">Ver todos los pedidos →</button></div>${orderTable(data.orders.slice(0,4),true)}<div class="table-foot">El balance representa ingresos menos gastos registrados. Para conocer tus ganancias reales, registra todos los costos.</div></section>`}
function orders(){const list=data.orders.filter(o=>(orderFilter==='all'||o.state===+orderFilter)&&`${o.client} ${o.detail} ${o.phone}`.toLocaleLowerCase('es').includes(orderSearch.toLocaleLowerCase('es')));const cl=clients(data.orders).filter(c=>`${c.name} ${c.phone}`.toLowerCase().includes(orderSearch.toLowerCase()));return heading('Cada pedido, en su lugar.','Del primer mensaje a la entrega. Tus clientes siempre a la mano.',btn('+ Nuevo pedido','new-order'))+`<div class="page-tabs"><button data-order-tab="orders" class="${orderTab==='orders'?'active':''}">Pedidos <small>(${data.orders.length})</small></button><button data-order-tab="clients" class="${orderTab==='clients'?'active':''}">Mis clientes <small>(${clients(data.orders).length})</small></button></div><div class="toolbar"><div class="search">${svg('search')}<label class="sr-only" for="order-search">Buscar pedidos o clientes</label><input id="order-search" placeholder="Buscar por cliente, producto o celular…" value="${esc(orderSearch)}"></div>${orderTab==='orders'?`<label class="sr-only" for="order-filter">Filtrar por estado</label><select class="filter-select" id="order-filter"><option value="all">Todos los estados</option>${STATES.map((s,i)=>`<option value="${i}" ${orderFilter===String(i)?'selected':''}>${s}</option>`).join('')}</select>`:''}</div><div id="order-results">${orderTab==='orders'?`<section class="panel">${list.length?orderTable(list):emptyBox(data.orders.length?'No encontramos coincidencias':'Aún no tienes pedidos',data.orders.length?'Prueba con otro nombre o cambia el filtro.':'Registra tu primera venta para organizar tu negocio.','orders',data.orders.length?'':'new-order')}<div class="table-foot">Haz clic en el estado para pasar de Pendiente a En proceso, luego a Entregado. Los entregados se suman automáticamente a Finanzas.</div></section>`:cl.length?`<div class="client-grid">${cl.map(c=>`<article class="client-card"><span class="avatar">${esc(initials(c.name))}</span><h3>${esc(c.name)}</h3><p>${esc(c.phone||'Sin celular registrado')}</p><div class="client-card-footer"><span>${c.count} pedido${c.count>1?'s':''}</span><strong>${money(c.total)}</strong></div></article>`).join('')}</div><p class="hint">Los clientes se agrupan por nombre. El total corresponde al importe de todos sus pedidos, incluidos los pendientes.</p>`:emptyBox('Aquí empieza una buena relación','Tus clientes aparecen automáticamente al registrar pedidos.','client','new-order')}</div>`}
function costs(){const c=data.calculator;return heading('Ponle un precio justo a tu trabajo.','Conserva el cálculo original y conoce también tu margen real.',btn('✦ Ayúdame con mis precios','copilot','btn secondary'))+`<div class="calc-layout"><section class="panel"><h2>Costos y precios</h2><div class="field-grid"><label>Costo de insumos (S/)<input data-calc="materials" type="number" min="0" max="1000000000" step="0.01" value="${c.materials}"></label><label>Otros costos (S/)<input data-calc="other" type="number" min="0" max="1000000000" step="0.01" value="${c.other}"></label><label>Porcentaje deseado (%)<input data-calc="percent" type="number" min="0" max="1000" step="0.01" value="${c.percent}"></label><label>Unidades que salen<input data-calc="units" type="number" min="1" max="1000000" step="1" value="${c.units}"></label></div><label>Cómo aplicar el porcentaje<select data-calc="mode"><option value="markup" ${c.mode==='markup'?'selected':''}>Recargo sobre el costo · Fórmula original</option><option value="margin" ${c.mode==='margin'?'selected':''}>Margen sobre el precio de venta</option></select></label><div class="hint">La versión antigua llama “margen” al recargo sobre costo. Aquí puedes elegir ambas fórmulas. Con S/ 25 de costo y 40% de recargo, el precio es S/ 35 y el margen sobre venta es 28.57%.</div><div class="sector-tip"><h3>Para ${esc(data.sector||'tu negocio')}</h3>${cfg().tips.map(t=>`<p>✓ ${esc(t)}</p>`).join('')}</div></section><section class="result-card" id="cost-result"></section></div><section class="panel"><div class="panel-header"><div><h2>Tu catálogo de costos</h2><p>Guarda cálculos para tus productos o servicios.</p></div></div>${data.products.length?`<div class="table-scroll"><table><thead><tr><th>PRODUCTO / SERVICIO</th><th>COSTO UNITARIO</th><th>PRECIO SUGERIDO</th><th>GANANCIA UNITARIA</th><th>ACCIONES</th></tr></thead><tbody>${data.products.map(p=>`<tr><td>${esc(p.name)}</td><td>${money(p.cost)}</td><td>${money(p.price)}</td><td class="${p.price<p.cost?'negative':'positive'}">${money(round(p.price-p.cost))}</td><td>${actions('product',p.id)}</td></tr>`).join('')}</tbody></table></div>`:emptyBox('Tu trabajo vale. Guarda su costo.','Calcula un precio y guárdalo en tu catálogo.','costs')}</section>`}
function drawCostResult(){if(page!=='costs')return;try{const r=calculate(data.calculator);$('cost-result').innerHTML=`<small>PRECIO SUGERIDO POR UNIDAD</small><div class="result-price">${money(r.price)}</div><div class="result-line"><span>Costo por unidad</span><strong>${money(r.cost)}</strong></div><div class="result-line"><span>Ganancia por unidad</span><strong>${money(r.profit)}</strong></div><div class="result-line"><span>Margen sobre venta</span><strong>${r.actualMargin}%</strong></div><p>Es una referencia basada en los costos ingresados. Considera tu tiempo, delivery, comisiones e impuestos cuando correspondan.</p>${btn('Guardar en mi catálogo →','save-product')}`;}catch(e){$('cost-result').innerHTML=`<small>REVISA TU CÁLCULO</small><p>${esc(e.message)}</p>`}}
function finances(){const t=totals(data,financeMonth);const months=[...new Set([today().slice(0,7),...data.orders.map(o=>(o.deliveredAt||o.created||'').slice(0,7)),...data.movements.map(m=>(m.date||'').slice(0,7))])].filter(Boolean).sort().reverse();const list=[...t.sales.filter(o=>o.amount>0).map(o=>({id:o.id,type:'Ingreso',amount:o.amount,concept:`Pedido entregado · ${o.client}`,date:o.deliveredAt||o.created,auto:true})),...t.movements].sort((a,b)=>(b.date||'').localeCompare(a.date||''));return heading('Tus números, con claridad.','Ingresos, gastos y balance. Sin hojas sueltas.',`<label class="sr-only" for="finance-month">Periodo financiero</label><select class="month-filter" id="finance-month"><option value="all">Todo el historial</option>${months.map(m=>`<option value="${m}" ${financeMonth===m?'selected':''}>${new Intl.DateTimeFormat('es-PE',{month:'long',year:'numeric'}).format(new Date(m+'-15T12:00:00Z'))}</option>`).join('')}</select>`+btn('+ Registrar movimiento','new-movement'))+`<div class="stats finance-stats">${stat('Ingresos',money(t.income),`${money(t.auto)} automáticos + ${money(t.manual)} manuales`,'finances','positive')}${stat('Gastos',money(t.expenses),'Costos registrados como movimientos','costs','negative')}${stat('Balance registrado',money(t.net),'Ingresos menos gastos; completa todos tus costos','finances',t.net<0?'negative':'positive')}</div><section class="panel"><div class="panel-header"><h2>Movimientos del negocio</h2><span>${list.length} movimiento${list.length!==1?'s':''}</span></div>${list.length?`<div class="table-scroll"><table><thead><tr><th>CONCEPTO</th><th>FECHA</th><th>TIPO</th><th style="text-align:right">IMPORTE</th><th>ACCIONES</th></tr></thead><tbody>${list.map(m=>`<tr><td><strong style="font-weight:500">${esc(m.concept)}</strong><br>${m.auto?'<span class="auto-label">Desde pedido · automático</span>':`<small>${esc(m.category||'Movimiento manual')}</small>`}</td><td>${dateLabel(m.date)}</td><td>${m.type}</td><td class="money-cell ${m.type==='Ingreso'?'positive':'negative'}">${m.type==='Ingreso'?'+':'−'} ${money(m.amount)}</td><td>${m.auto?`<button class="panel-link" data-action="edit-order" data-id="${esc(m.id)}">Ver pedido →</button>`:actions('movement',m.id)}</td></tr>`).join('')}</tbody></table></div>`:emptyBox('Tus finanzas empiezan con un movimiento','Registra un ingreso o gasto. Los pedidos entregados aparecerán automáticamente.','finances','new-movement')}<div class="table-foot">Los pedidos entregados se contabilizan una sola vez. Si cambias su estado o importe, el ingreso se actualiza. No vuelvas a registrar esa misma venta como ingreso manual.<br>Los registros antiguos sin fecha se muestran en cualquier periodo y se identifican como “Sin fecha”.</div></section>`}
function reminders(){const t=today(),list=data.reminders.filter(r=>reminderFilter==='all'||(reminderFilter==='done'?r.done:reminderFilter==='overdue'?!r.done&&r.date&&r.date<t:!r.done)).sort((a,b)=>Number(a.done)-Number(b.done)||(a.date||'9999').localeCompare(b.date||'9999')||(a.time||'').localeCompare(b.time||''));return heading('Lo importante, siempre presente.','Pagos, entregas y citas. Tu negocio también necesita una agenda.',btn('+ Nuevo recordatorio','new-reminder'))+`<div class="segmented">${[['pending','Pendientes'],['overdue','Vencidos'],['done','Completados'],['all','Todos']].map(([k,v])=>`<button data-reminder-filter="${k}" class="${reminderFilter===k?'active':''}">${v}</button>`).join('')}</div>${list.length?`<div class="reminder-list">${list.map(r=>`<article class="reminder-card ${r.done?'done':''} ${!r.done&&r.date&&r.date<t?'overdue':''}"><input type="checkbox" ${r.done?'checked':''} data-action="toggle-reminder" data-id="${esc(r.id)}" aria-label="${r.done?'Reabrir':'Completar'} ${esc(r.title)}"><div><h3>${esc(r.title)}</h3><p>${!r.done&&r.date&&r.date<t?'Vencido · ':r.date===t?'Hoy · ':''}${fullDate(r.date)}${r.time?' · '+esc(r.time):''}</p></div><span class="kind">${r.kind}</span>${actions('reminder',r.id)}</article>`).join('')}</div>`:emptyBox('Todo en orden por aquí',reminderFilter==='overdue'?'No tienes recordatorios vencidos.':'Agrega un pago, una entrega o una cita y no lo dejes a tu memoria.','reminders',reminderFilter==='pending'||reminderFilter==='all'?'new-reminder':'')}<div class="hint">Estos recordatorios se muestran al abrir la plataforma. El envío automático por WhatsApp y las notificaciones externas no están conectados en esta versión de prueba.</div>`}
const legacyExport=`(()=>{const s=localStorage.getItem('ec2');if(!s){alert('No hay datos ec2 en este navegador');return;}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:'application/json'}));a.download='emprendecopilot-antiguo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);})();`;
function settings(){return heading('Un espacio a la medida de tu negocio.','Tu rubro, tus datos y tus respaldos. Todo en tus manos.')+`<div class="settings-layout"><section class="panel"><h2>Mi negocio</h2><form id="business-settings"><label>Nombre de tu negocio<input name="business" value="${esc(data.business)}" maxlength="120" required placeholder="Ej. Dulce Antojo"></label><label>Tu nombre <small>Opcional</small><input name="owner" maxlength="80" value="${esc(data.owner)}" placeholder="Ej. Claudia"></label><label>Rubro<select name="sector" required><option value="">Selecciona tu rubro</option>${Object.keys(SECTORS).map(s=>`<option ${data.sector===s?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn" type="submit">Guardar mi negocio →</button></form>${data.sector?`<div class="sector-tip"><h3>Recomendaciones para ${esc(data.sector)}</h3>${cfg().tips.map(t=>`<p>✓ ${esc(t)}</p>`).join('')}<p>Categorías sugeridas: ${esc(cfg().categories.join(', '))}</p></div>`:''}</section><section class="panel"><h2>Mis datos y respaldos</h2><div class="data-block"><h3>Un respaldo, más tranquilidad.</h3><p>Los registros se guardan en este navegador. No se sincronizan entre dispositivos. Guarda un respaldo para trasladarlos o recuperarlos.</p><div class="data-actions">${btn('↓ Exportar respaldo','export','btn secondary small')}${btn('↑ Importar respaldo','import','btn secondary small')}</div></div><div class="data-block"><h3>Prueba la plataforma con ejemplos.</h3><p>Puedes cargar pedidos, gastos y recordatorios ficticios para explorar. Se añaden a tus datos actuales, sin reemplazarlos.</p>${btn('Cargar ejemplos de prueba','sample','btn ghost small')}</div><h3 style="font-size:11px">Importar desde la plataforma antigua</h3><div class="settings-detail"><p>La versión anterior guarda en la clave <strong>ec2</strong>. Si ya existe en este mismo origen, se importa al iniciar. Para traer datos desde Netlify:</p><ol><li>Abre tu plataforma antigua en el navegador donde registraste tus datos.</li><li>Abre las herramientas del navegador (F12), pestaña Consola. Revisa este código y ejecútalo para descargar el respaldo.</li><li>Vuelve aquí y selecciona “Importar respaldo”.</li></ol><code>${esc(legacyExport)}</code><p>El script solo descarga el guardado local; no lo envía a ningún servidor. La importación permite combinar datos o reemplazar después de descargar un respaldo.</p></div></section></div>`}
function labelTables(){document.querySelectorAll('#content table').forEach(table=>{const labels=Array.from(table.querySelectorAll('thead th')).map(th=>th.textContent.trim());table.querySelectorAll('tbody tr').forEach(row=>Array.from(row.children).forEach((cell,index)=>{cell.dataset.label=labels[index]||'Acciones';}));});}
function render(){nav();$('content').innerHTML=({home,orders,costs,finances,reminders,settings}[page])();drawCostResult();labelTables();if(page==='orders')bindSearch();if(page==='settings')$('business-settings').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);data.business=String(f.get('business')).trim();data.owner=String(f.get('owner')).trim();data.sector=String(f.get('sector'));if(!data.business)return;changed('Tu negocio está configurado.');});}
function bindSearch(){$('order-search').addEventListener('input',e=>{orderSearch=e.target.value;const temporary=document.createElement('div');temporary.innerHTML=orders();$('order-results').innerHTML=temporary.querySelector('#order-results').innerHTML;labelTables();});$('order-filter')?.addEventListener('change',e=>{orderFilter=e.target.value;render()});}
const editor=$('editor');
const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,options,value)=>`<label>${label}<select name="${name}" aria-label="${esc(label)}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
function openForm(type,id='',preset={}){const collection={order:'orders',movement:'movements',reminder:'reminders',product:'products'}[type];const item=collection?data[collection].find(x=>x.id===id):null;const o=item||preset;let title='',subtitle='',body='';
 if(type==='order'){title=item?'Editar pedido':'Nuevo pedido';subtitle='Registra lo que tu cliente necesita. Lo demás, en orden.';body=`<div class="field-grid">${field('Nombre del cliente *','client',o.client,'text','required maxlength="120" autocomplete="name"')}${field('Celular (opcional)','phone',o.phone,'tel','maxlength="40" autocomplete="tel"')}</div><label>Detalle del pedido *<textarea name="detail" required maxlength="1000" placeholder="${esc(cfg().example)}">${esc(o.detail||'')}</textarea></label><div class="field-grid">${field('Monto (S/)','amount',o.amount??'','number','min="0" max="1000000000" step="0.01" placeholder="0.00"')}${field('Fecha de entrega','delivery',o.delivery,'date')}</div>${select('Estado','state',STATES.map((s,i)=>[i,s]),o.state||0)}<label>Notas (opcional)<textarea name="notes" maxlength="1000" placeholder="Talla, dirección, indicaciones…">${esc(o.notes||'')}</textarea></label>`;}
 if(type==='movement'){title=item?'Editar movimiento':'Registrar movimiento';subtitle='Completa el balance de tu negocio, movimiento a movimiento.';body=`<div class="field-grid">${select('Tipo','type',[['Ingreso','Ingreso'],['Gasto','Gasto']],o.type||'Gasto')}${field('Monto (S/) *','amount',o.amount??'','number','required min="0.01" max="1000000000" step="0.01"')}</div>${field('Concepto *','concept',o.concept,'text','required maxlength="250" placeholder="Ej. compra de insumos" list="expense-categories"')}<datalist id="expense-categories">${cfg().categories.map(c=>`<option value="${esc(c)}">`).join('')}</datalist><div class="field-grid">${field('Fecha','date',o.date??today(),'date')}${field('Categoría (opcional)','category',o.category,'text','maxlength="80" list="expense-categories"')}</div><div class="hint">Los pedidos entregados ya generan ingresos automáticos. Registra aquí otras entradas o tus gastos para evitar duplicar una venta.</div>`;}
 if(type==='reminder'){title=item?'Editar recordatorio':'Nuevo recordatorio';subtitle='Que los pendientes no dependan solo de tu memoria.';body=field('¿Qué necesitas recordar? *','title',o.title,'text','required maxlength="250" placeholder="Ej. Cobrar seña a Lucía"')+select('Tipo de recordatorio','kind',['Pago','Entrega','Cita'].map(s=>[s,s]),o.kind||'Pago')+`<div class="field-grid">${field('Fecha','date',o.date??'','date')}${field('Hora (opcional)','time',o.time,'time')}</div>`;}
 if(type==='business'){title='Este es tu espacio.';subtitle='Elige el rubro y personalizamos los ejemplos y recomendaciones.';body=field('Nombre de tu negocio *','business',data.business,'text','required maxlength="120" placeholder="Ej. Dulce Antojo"')+field('Tu nombre (opcional)','owner',data.owner,'text','maxlength="80"')+select('Rubro *','sector',[['','Selecciona tu rubro'],...Object.keys(SECTORS).map(s=>[s,s])],data.sector);}
 if(type==='product'){let r={cost:0,price:0};try{r=calculate(data.calculator)}catch{}title=item?'Editar producto o servicio':'Guardar cálculo';subtitle='Ten tus costos y precios siempre a la mano.';body=field('Producto o servicio *','name',o.name,'text','required maxlength="150" placeholder="Ej. Torta de chocolate"')+`<div class="field-grid">${field('Costo unitario (S/) *','cost',o.cost??r.cost,'number','required min="0" max="1000000000" step="0.01"')}${field('Precio sugerido (S/) *','price',o.price??r.price,'number','required min="0" max="1000000000" step="0.01"')}</div>`;}
 $('editor-content').innerHTML=`<div class="dialog-heading"><small>EMPRENDECOPILOT / ${item?'EDITAR':'CREAR'}</small><h2>${title}</h2><p>${subtitle}</p></div><form id="record-form">${body}<div class="form-error" id="form-error" role="alert"></div><div class="form-actions">${btn('Cancelar','close-editor','btn secondary')}<button class="btn" type="submit">${item?'Guardar cambios':'Guardar'} →</button></div></form>`;$('record-form').addEventListener('submit',e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(v))v[k]=v[k].trim();const n=k=>{const value=Number(v[k]||0);if(!Number.isFinite(value)||value<0||value>1e9)throw Error('Revisa los montos ingresados.');return round(value)};const validDate=s=>{if(s&&(!/^\d{4}-\d{2}-\d{2}$/.test(s)||new Date(s+'T12:00:00Z').toISOString().slice(0,10)!==s))throw Error('Fecha inválida.');return s};let next;
 if(type==='order'){if(!v.client||!v.detail)throw Error('Completa el cliente y el detalle.');const state=Number(v.state);next={...item,id:item?.id||uid(),client:v.client,phone:v.phone,detail:v.detail,amount:n('amount'),state,delivery:validDate(v.delivery),notes:v.notes,created:item?.created??today(),deliveredAt:state===2?(item?.state===2?item.deliveredAt||'':today()):''};}
 if(type==='movement'){if(!v.concept||n('amount')<=0)throw Error('Completa el concepto y un monto mayor a cero.');next={id:item?.id||uid(),type:v.type,amount:n('amount'),concept:v.concept,date:validDate(v.date),category:v.category};}
 if(type==='reminder'){if(!v.title)throw Error('Escribe el recordatorio.');next={id:item?.id||uid(),title:v.title,kind:v.kind,date:validDate(v.date),time:v.time,done:item?.done||false};}
 if(type==='product'){if(!v.name)throw Error('Escribe el nombre del producto.');next={id:item?.id||uid(),name:v.name,cost:n('cost'),price:n('price')};}
 if(type==='business'){if(!v.business||!SECTORS[v.sector])throw Error('Completa el nombre del negocio y selecciona el rubro.');data.business=v.business;data.owner=v.owner;data.sector=v.sector;}else if(item){data[collection][data[collection].findIndex(x=>x.id===id)]=next}else data[collection].unshift(next);
 editor.close();changed(item?'Cambios guardados.':'Listo. Guardado en tu negocio.');}catch(err){$('form-error').textContent=err.message;}});editor.showModal();}
function remove(type,id){const col={order:'orders',movement:'movements',reminder:'reminders',product:'products'}[type];const index=data[col].findIndex(x=>x.id===id);if(index<0)return;const item=data[col].splice(index,1)[0];persist();render();notice('Registro eliminado. Puedes deshacerlo.',()=>{data[col].splice(Math.min(index,data[col].length),0,item);changed('Registro recuperado.');});}
function exportBackup(){const blob=new Blob([JSON.stringify({...data,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`EmprendeCopilot-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function sample(){if(data.orders.some(o=>o.id.startsWith('sample-'))){notice('Los ejemplos ya están cargados.');return}const d=today();const prev=new Date(d+'T12:00:00Z');prev.setUTCDate(prev.getUTCDate()-1);const yesterday=prev.toISOString().slice(0,10);const future=new Date(d+'T12:00:00Z');future.setUTCDate(future.getUTCDate()+1);const next=future.toISOString().slice(0,10);if(!data.business)data.business='Dulces de Claudia · Ejemplo';if(!data.sector)data.sector='Repostería';if(!data.owner)data.owner='Claudia';const sampleOrders=[{id:'sample-order-1',client:'María Castillo · Ejemplo',phone:'',detail:'Torta de chocolate · Datos ficticios',amount:85,state:1,delivery:next,created:d,deliveredAt:'',notes:''},{id:'sample-order-2',client:'José López · Ejemplo',phone:'',detail:'Box de cupcakes · Datos ficticios',amount:45,state:2,delivery:yesterday,created:yesterday,deliveredAt:yesterday,notes:''},{id:'sample-order-3',client:'Ana Paredes · Ejemplo',phone:'',detail:'Cheesecake familiar · Datos ficticios',amount:70,state:0,delivery:next,created:d,deliveredAt:'',notes:''}];data.orders.unshift(...sampleOrders);data.movements.push({id:'sample-move-1',type:'Gasto',amount:20,concept:'Insumos · Ejemplo',category:'Insumos',date:yesterday},{id:'sample-move-2',type:'Ingreso',amount:25,concept:'Venta en feria · Ejemplo',category:'Venta',date:d});data.reminders.push({id:'sample-reminder-1',title:'Entregar torta de María · Ejemplo',kind:'Entrega',date:next,time:'10:00',done:false},{id:'sample-reminder-2',title:'Confirmar seña de Ana · Ejemplo',kind:'Pago',date:d,time:'14:00',done:false});changed('Ejemplos ficticios añadidos. Puedes editar o eliminar cada registro.');}
function importPreview(){const d=importData;$('editor-content').innerHTML=`<div class="dialog-heading"><small>RESPALDO DE EMPRENDECOPILOT</small><h2>Tu información, lista para volver.</h2><p>Revisa el contenido antes de importarlo.</p></div><div class="import-summary"><strong>${esc(d.business||'Negocio sin nombre')}</strong><br>Rubro: ${esc(d.sector||'Sin rubro')}<br>${d.orders.length} pedidos · ${d.movements.length} movimientos<br>${d.reminders.length} recordatorios · ${d.products.length} productos</div><p class="hint">Combinar mantiene tus registros actuales. Los respaldos de la versión 3 evitan duplicados por ID; los de ec2 generan nuevos IDs al importarse. Importa un archivo ec2 una sola vez.</p><div class="form-actions">${btn('Combinar con mis datos','import-merge')}${btn('Reemplazar con respaldo previo','import-replace','btn secondary')}</div>`;editor.showModal();}
function performImport(replace){if(!importData)return;if(replace){exportBackup();data=importData;}else{for(const col of ['orders','movements','reminders','products']){const ids=new Set(data[col].map(x=>x.id));data[col].push(...importData[col].filter(x=>!ids.has(x.id)))}if(!data.business)data.business=importData.business;if(!data.sector)data.sector=importData.sector;if(!data.owner)data.owner=importData.owner;}importData=null;editor.close();changed('Respaldo importado.');}
function reply(q){const text=q.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const t=totals(data);if(/precio|costo|margen|recargo/.test(text)){let r;try{r=calculate(data.calculator)}catch{return 'Revisa los valores de Costos para que pueda ayudarte con el cálculo.';}return `Con tus valores actuales:\n• Costo por unidad: ${money(r.cost)}\n• Precio sugerido: ${money(r.price)}\n• Ganancia por unidad: ${money(r.profit)}\n• Margen sobre venta: ${r.actualMargin}%\n\n${cfg().tips[0]}\nPuedes cambiar los valores en Costos y guardar el resultado en tu catálogo.`;}
 if(/respuesta|responder|mensaje|whatsapp/.test(text)){const o=data.orders.find(o=>o.state!==2)||data.orders[0];if(!o)return 'Registra un pedido en Pedidos. Después podré preparar una respuesta con el nombre del cliente, detalle y estado. No envío mensajes automáticamente.';return `Borrador para ${o.client}:\n\n“¡Hola, ${o.client.split(' ')[0]}! Te escribo sobre tu pedido: ${o.detail}. Actualmente está ${STATES[o.state].toLowerCase()}${o.delivery?', con entrega prevista para el '+fullDate(o.delivery):''}. Si necesitas algo más, estoy aquí para ayudarte. ¡Gracias por confiar en ${data.business||'nosotros'}!”\n\nRevisa el texto y los datos antes de enviarlo. Es un borrador de prueba, no un envío automático.`;}
 if(/pendiente|recordatorio|entrega|agenda/.test(text)){const pending=data.reminders.filter(r=>!r.done).sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999'));return `Tienes ${t.pending} pedidos por entregar y ${pending.length} recordatorios pendientes.\n\n${pending.slice(0,5).map(r=>'• '+r.title+' · '+fullDate(r.date)+(r.date&&r.date<today()?' · Vencido':'')).join('\n')||'Tu agenda está libre. Puedes crear recordatorios de pagos, entregas o citas.'}\n\nLos pedidos pendientes suman ${money(t.receivable)}. Este importe no indica pagos pendientes: la plataforma no registra si cada pedido ya fue pagado.`;}
 if(/cliente/.test(text)){const c=clients(data.orders);return c.length?`Tienes ${c.length} clientes registrados a partir de tus pedidos.\n\n${c.slice(0,4).map(c=>'• '+c.name+': '+c.count+' pedidos · '+money(c.total)).join('\n')}\n\nEn Pedidos → Mis clientes puedes revisar sus celulares e importes. Los clientes se agrupan por nombre; usa el mismo nombre en cada compra.`:'Tus clientes aparecerán automáticamente al registrar pedidos. Comienza por su nombre y agrega su celular si lo tienes.';}
 if(/resumen|negocio|ganancia|ingreso|gasto|finanza|venta/.test(text)){return `Este es el resumen de ${data.business||'tu negocio'}:\n\n• Ingresos: ${money(t.income)}\n• Gastos: ${money(t.expenses)}\n• Balance registrado: ${money(t.net)}\n• Pedidos por entregar: ${t.pending}\n\n${recommendations(data).map(r=>'→ '+r.title+': '+r.body).join('\n')}\n\nEl balance depende de que registres todos tus gastos. No es una proyección ni una garantía de ganancias.`;}
 if(/rubro|consejo|recomenda|crecer|ayuda/.test(text))return `Para ${data.sector||'tu emprendimiento'}:\n\n${cfg().tips.map(t=>'• '+t).join('\n')}\n\nPrimero registra tus pedidos; luego calcula tus precios y anota tus gastos. Puedes preguntarme por tu resumen, pendientes o respuestas a clientes.`;
 return 'Soy tu Copilot de prueba. Puedo usar los datos registrados para resumir tu negocio, revisar pendientes, calcular tus precios o redactar un borrador para un cliente. Prueba: “Resume mi negocio” o “Qué pendientes tengo”.';}
function addChat(content,role){const bubble=document.createElement('div');bubble.className='chat-message '+role;if(role==='assistant'){const small=document.createElement('small');small.textContent='COPILOT · RESPUESTA DE PRUEBA';bubble.append(small)}bubble.append(document.createTextNode(content));$('chat-messages').append(bubble);$('chat-messages').scrollTop=$('chat-messages').scrollHeight;}
function openCopilot(){if(!$('chat-messages').children.length)addChat(`Hola${data.owner?', '+data.owner:''}. Estoy aquí para ayudarte a poner tu negocio en orden. ¿Revisamos tus pedidos, costos o pendientes?`,'assistant');$('copilot').showModal();$('chat-input').focus();}
function ask(q){if(!q.trim())return;addChat(q.slice(0,500),'user');addChat(reply(q),'assistant');$('chat-input').value='';}
function closeMenu(){$('sidebar').classList.remove('open');$('sidebar-overlay').hidden=true;$('mobile-menu').setAttribute('aria-expanded','false');}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){go(p.dataset.page);return}const ot=e.target.closest('[data-order-tab]');if(ot){orderTab=ot.dataset.orderTab;render();return}const rf=e.target.closest('[data-reminder-filter]');if(rf){reminderFilter=rf.dataset.reminderFilter;render();return}const q=e.target.closest('[data-question]');if(q){ask(q.dataset.question);return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;
 if(a==='copilot')openCopilot();else if(a==='business')openForm('business');else if(a.startsWith('new-'))openForm(a.slice(4));else if(a.startsWith('edit-'))openForm(a.slice(5),id);else if(a.startsWith('delete-'))remove(a.slice(7),id);else if(a==='close-editor')editor.close();else if(a==='save-product')openForm('product');else if(a==='cycle-order'){const o=data.orders.find(o=>o.id===id);if(o){o.state=(o.state+1)%3;o.deliveredAt=o.state===2?today():'';changed('Estado actualizado. Finanzas se recalculó.');}}else if(a==='toggle-reminder'){const r=data.reminders.find(r=>r.id===id);if(r){r.done=!r.done;changed(r.done?'Recordatorio completado.':'Recordatorio reabierto.');}}else if(a==='export')exportBackup();else if(a==='import')$('import-file').click();else if(a==='sample')sample();else if(a==='import-merge')performImport(false);else if(a==='import-replace')performImport(true);
});
document.addEventListener('input',e=>{if(e.target.dataset.calc){const key=e.target.dataset.calc;const value=key==='mode'?e.target.value:Number(e.target.value);data.calculator[key]=value;try{calculate(data.calculator);persist()}catch{}drawCostResult();}});
document.addEventListener('change',e=>{if(e.target.dataset.calc){data.calculator[e.target.dataset.calc]=e.target.dataset.calc==='mode'?e.target.value:Number(e.target.value);try{calculate(data.calculator);persist()}catch{}drawCostResult()}if(e.target.id==='finance-month'){financeMonth=e.target.value;render()}});
$('import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('El archivo supera 5 MB.');importData=normalize(JSON.parse(await file.text()));importPreview()}catch(err){notice('No se pudo importar: '+err.message)}});
$('mobile-menu').addEventListener('click',()=>{const isOpen=$('sidebar').classList.toggle('open');$('sidebar-overlay').hidden=!isOpen;$('mobile-menu').setAttribute('aria-expanded',String(isOpen));});$('sidebar-overlay').addEventListener('click',closeMenu);document.querySelector('.dialog-close').addEventListener('click',()=>editor.close());$('close-copilot').addEventListener('click',()=>$('copilot').close());$('chat-form').addEventListener('submit',e=>{e.preventDefault();ask($('chat-input').value)});$('toast').querySelector('button').addEventListener('click',()=>{const cb=undo;undo=null;$('toast').hidden=true;cb?.()});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(labels[p]&&p!==page){page=p;render();closeMenu()}});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});
page=labels[location.hash.slice(1)]?location.hash.slice(1):'home';render();
